select @ngay_bc as ngay_bc, @ngay_bc2 as ngay_bc2
declare @thang int = month(@ngay_bc), @nam int = year(@ngay_bc)
exec zrpt_O025  @thang, @nam, @ngay_bc2, @tk_thue, @ma_dvcs, '@@sysDatabaseName', @@language, @@userID, @@admin

			
		
	

	
		
			&OutlineEntry;
			&JavascriptReportFilter; 
			
function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete); 
	changeLookupReadonly(f, 'ma_dvcs');
	changeLookupReadonly(f, 'tk_thue');
}
function close$VoucherFilter$(f) {
	try {f.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}
}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			g._hiddenForms = [];
			g._alterTitle = [null, [['%s1', f.getItem('ngay_bc').value, true], ['%s2', f.getItem('ngay_bc2').value, true]]];
			//remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}

		
	

